// Get Wikipedia search results
const wikiData = $input.first().json;
let searchResults = [];

// Extract search results
if (wikiData.query && wikiData.query.search) {
  wikiData.query.search.forEach((result, i) => {
    searchResults.push({
      title: result.title,
      description: result.snippet.replace(/<[^>]*>/g, ''), // Remove HTML tags
      url: `https://en.wikipedia.org/wiki/${result.title.replace(/ /g, '_')}`
    });
  });
}

// Format for AI consumption
const formattedText = searchResults.map((result, i) => 
  `${i + 1}. ${result.title}\n${result.description}\nSource: ${result.url}\n`
).join('\n');

// Get data from previous nodes - MATCH THE NEW FIELD NAMES
const previousData = $('Clean from Data').first().json;

// Return the data
return [{
  json: {
    subject: previousData.subject,        // lowercase
    email: previousData.email,            // lowercase
    report_type: previousData.report_type,
    searchResults: searchResults,
    formattedSearchText: formattedText,
    totalResults: searchResults.length
  }
}];

const data = $input.first().json;

const requestBody = {
  model: "llama-3.3-70b-versatile",  // UPDATED MODEL
  messages: [
    {
      role: "system",
      content: "You are a professional research assistant. Create comprehensive, well-structured research reports based on the information provided."
    },
    {
      role: "user",
      content: `Create a ${data.report_type} research report on: ${data.subject}\n\nBased on these search results:\n${data.formattedSearchText}\n\nReport requirements:\n- Quick: 300-500 words with key findings\n- Standard: 1000-1500 words with analysis\n- Extended: 2500+ words with deep analysis and sources`
    }
  ],
  temperature: 0.7,
  max_tokens: 4000
};

return [{
  json: requestBody
}];

// Get the AI response from Groq
const groqResponse = $input.first().json;

// Extract the generated report
const report = groqResponse.choices[0].message.content;

// Get the original data (subject, email, etc.)
const originalData = $('Code in JavaScript').first().json;

// Return everything together
return [{
  json: {
    subject: originalData.subject,
    email: originalData.email,
    report_type: originalData.report_type,
    report: report,
    sources: originalData.searchResults
  }
}];

