// Create plain text version
const plainText = `
Research Report: ${data.subject}
Report Type: ${reportTypeNames[data.report_type] || data.report_type}

${data.report}

Sources Used:
${data.sources.map((source, i) => `${i + 1}. ${source.title}\n   ${source.url}`).join('\n')}

---
Generated by AI Research Assistant
`;

return [{
  json: {
    to: data.email,
    subject: `Research Report: ${data.subject}`,
    html: emailHTML,
    text: plainText
  }
}];
